import{_ as a,o as n,c as i,a6 as s}from"./chunks/framework.CKIbuWFA.js";const m=JSON.parse('{"title":"Entender rankings y competiciones","description":"","frontmatter":{"title":"Entender rankings y competiciones","docId":"user.points.rankings","translationKey":"user.points.rankings","locale":"es","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"dcf08e4ef08a28fc3e32216b2017b5f208afc57a91e537fd3b90a6f0ed1f041e","translationRevision":"8b37cd7f574ca55b6fbbac3738af4008a1ffd5436bc0417acfe80a1974c9b429","order":30},"headers":[],"relativePath":"es/user/points/rankings.md","filePath":"es/user/points/rankings.md","lastUpdated":1794611623000}'),r={name:"es/user/points/rankings.md"};function t(o,e,d,c,l,u){return n(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="understand-rankings-and-competitions" tabindex="-1">Entender rankings y competiciones <a class="header-anchor" href="#understand-rankings-and-competitions" aria-label="Permalink to &quot;Entender rankings y competiciones {#understand-rankings-and-competitions}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Elige la clasificación adecuada y reconoce los límites del espacio de rankings en desarrollo. Necesitas actividad entrante para obtener puntuaciones útiles. Comienza con la tabla habitual de <a href="./rules.html">Points</a> o los paneles de espectadores destacados del <a href="./../live/feed.html">feed LIVE</a> si solo deseas consultar participantes actuales.</p><h2 id="use-the-right-view" tabindex="-1">Elegir la vista <a class="header-anchor" href="#use-the-right-view" aria-label="Permalink to &quot;Elegir la vista {#use-the-right-view}&quot;">​</a></h2><ol><li>En <strong>Points</strong>, busca un espectador y ordena por puntos, nivel o identidad. Actualiza antes de comparar un ajuste manual con una asignación.</li><li>En <strong>Live feed</strong>, revisa los paneles de espectadores clasificados disponibles. Pueden recibir instantáneas del motor de rankings independientemente de la tabla de saldos.</li><li>Para una superposición, abre <a href="./../overlays/">Overlays</a>, selecciona el tipo de ranking y revisa sus fuentes. La fuente configurada debe existir para que aparezcan resultados.</li></ol><p>El espacio dedicado <strong>Rankings &amp; competitions</strong> es experimental. Su ruta de frontend es <code>#/rankings</code>, pero está oculto deliberadamente en la navegación principal y no se recupera como pestaña de inicio. La ausencia en la barra lateral no significa que se hayan eliminado la ruta o el motor.</p><h2 id="configure-an-experimental-ranking" tabindex="-1">Configurar un ranking experimental <a class="header-anchor" href="#configure-an-experimental-ranking" aria-label="Permalink to &quot;Configurar un ranking experimental {#configure-an-experimental-ranking}&quot;">​</a></h2><p>Si tu entorno permite acceder a ese espacio, comienza con un creador, una sala, agrupación por usuario y una ventana de sesión. Añade una métrica anunciada, como <code>tiktok.like</code> / <code>like.count</code>, con peso <code>1</code>. Establece un límite de resultados moderado y crea la definición. El formulario también admite ventanas móviles y diarias, con límites de duración y eventos o un desplazamiento horario explícito.</p><p>Lee la instantánea resultante antes de añadir fuentes. Pausar y reanudar afectan a la recopilación; reiniciar borra intencionalmente el estado del ranking. Las opciones de competición y las fuentes de votos tienen restricciones de agrupación propias. No supongas que reiniciar puntos reinicia una competición ni que toda agrupación personalizada admite cualquier métrica.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado y estado {#expected-result-and-status}&quot;">​</a></h2><p>Las tablas habituales están disponibles; la administración dedicada sigue siendo experimental. Las puntuaciones provienen del host, no de contar filas visibles. Esta guía no acredita aceptación real en emisión/OBS ni todas las combinaciones de competición.</p><h2 id="recovery" tabindex="-1">Recuperación <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperación {#recovery}&quot;">​</a></h2><p>Si no hay puntuaciones, revisa creador, sala, fuente activa, ventana y pausa. Retira combinaciones incompatibles en lugar de inventar campos. Conserva datos mediante <a href="./../preferences/backups.html">copias de seguridad</a> antes de reiniciar e incluye el ID de definición y el código de diagnóstico al informar de un fallo.</p><h2 id="operational-details" tabindex="-1">Detalles de operación <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalles de operación {#operational-details}&quot;">​</a></h2><p>La tabla de Points solicita 100 espectadores y filtra/ordena solo las filas recibidas. Refrescar u ordenar por nombre no consulta toda la base. Los rankings del feed muestran 10 filas por sesión de creador/sala: diamantes de regalos en Top y cantidades en Likes, con seguimiento limitado a 5.000 espectadores. No representan puntos guardados. Compara unidades y límites de sesión antes de comparar totales.</p>',15)])])}const f=a(r,[["render",t]]);export{m as __pageData,f as default};
